INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('pepperoni', (SELECT id FROM categories WHERE name = 'Піца'), 'Пепероні', 349, '32 см', '32', '/images/pizza-pepperoni.webp', 'ХІТ', 'Хрустке тісто 48-годинного дозрівання, соус із стиглих томатів пелаті, щедра порція тягучої моцарели та пікантна салямі пепероні з ароматом копчення.', 'Борошно з твердих сортів пшениці, соус із томатів пелаті, моцарела, пікантна пепероні, свіжий базилік', 'Глютен, молоко', 1, 1);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('margherita', (SELECT id FROM categories WHERE name = 'Піца'), 'Маргарита', 299, '32 см', '32', '/images/pizza-margherita.webp', '', 'Неаполітанська класика: стиглі італійські томати, ніжна волокниста моцарела, свіжий зелений базилік та крапля оливкової олії Extra Virgin.', 'Тісто довгої ферментації, томати пелаті, моцарела fior di latte, свіжий базилік, оливкова олія Extra Virgin', 'Глютен, молоко', 0, 2);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('hawaiian', (SELECT id FROM categories WHERE name = 'Піца'), 'Гавайська', 329, '32 см', '32', '/images/pizza-hawaiian.webp', '', 'Соковите куряче філе sous-vide, шматочки солодкого стиглого ананаса та подвійна порція розтопленої моцарели на ніжному вершковому соусі.', 'Тісто, томатно-вершковий соус, моцарела, ніжне філе курки, солодкий ананас', 'Глютен, молоко', 0, 3);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('meat', (SELECT id FROM categories WHERE name = 'Піца'), 'М’ясна', 369, '32 см', '32', '/images/pizza-meat.webp', 'СИТНО', 'Для великого апетиту: пікантна пепероні, ніжна шинка, соковите куряче філе та багато тягучої моцарели на насиченому томатному соусі з травами.', 'Тісто, томатний соус, моцарела, пепероні, шинка, маринована курка, орегано', 'Глютен, молоко', 0, 4);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('four-cheese', (SELECT id FROM categories WHERE name = 'Піца'), 'Чотири сири', 349, '32 см', '32', '/images/pizza-cheese.webp', 'СИРНИЙ ХІТ', 'Благородний сирний квартет: ніжна вершкова моцарела, пікантний блакитний дорблю, витриманий пармезан та насичений англійський чедер на вершках.', 'Тісто, фермерські вершки, моцарела, дорблю, витриманий пармезан, чедер', 'Глютен, молоко', 1, 5);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('bbq', (SELECT id FROM categories WHERE name = 'Піца'), 'Барбекю', 359, '32 см', '32', '/images/pizza-bbq.webp', '', 'Запечене куряче філе, хрусткий підсмажений бекон, солодкувата червона цибуля та фірмовий димний соус BBQ на тонкому рум’яному тісті.', 'Тісто, моцарела, куряче філе, копчений бекон, червона цибуля, фірмовий димний соус BBQ', 'Глютен, молоко, гірчиця', 0, 6);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('mushroom', (SELECT id FROM categories WHERE name = 'Піца'), 'Грибна', 339, '32 см', '32', '/images/pizza-mushroom.webp', '', 'Свіжі карамелізовані печериці, часниково-вершковий соус, розтоплена моцарела та дрібка прованських трав. Затишний смак у кожному шматочку.', 'Тісто, свіжі печериці, фермерські вершки, часник, моцарела, свіжа петрушка', 'Глютен, молоко', 0, 7);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('prosciutto', (SELECT id FROM categories WHERE name = 'Піца'), 'З прошуто', 389, '32 см', '32', '/images/pizza-prosciutto.webp', 'ПРЕМІУМ', 'Тонкі слайси в’яленого прошуто крудо, свіжа пряна рукола, пластівці витриманого пармезану та стиглі томати на оливковій олії Extra Virgin.', 'Тісто, томати пелаті, моцарела, італійське прошуто крудо, свіжа рукола, пластівці пармезану', 'Глютен, молоко', 0, 8);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('chief-burger', (SELECT id FROM categories WHERE name = 'Бургери'), 'Бургер Чіфс', 239, '300 г', '300', '/images/burger.webp', 'ХІТ', 'Соковита котлета зі 100% фермерської яловичини, розтоплений чедер, хрусткий салат айсберг, стиглий томат, маринований огірок і наш авторський смокі-соус у золотистій булочці бріош.', 'Булочка бріош із кунжутом, яловичина 100%, сир чедер, томат, салат айсберг, солоний огірок, фірмовий соус Чіфс', 'Глютен, молоко, яйця, кунжут, гірчиця', 1, 9);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('double-burger', (SELECT id FROM categories WHERE name = 'Бургери'), 'Подвійний чіз', 299, '420 г', '420', '/images/double-burger.webp', 'СИТНИЙ ХІТ', 'Дві соковиті котлети зі 100% яловичини, подвійний розплавлений чедер, хрусткі пікантні корнішони, кримська цибуля та фірмовий соус. Максимум м’яса для справжнього голоду.', 'Булочка бріош, дві котлети з яловичини, подвійний чедер, корнішони, червона цибуля, авторський бургер-соус', 'Глютен, молоко, яйця, кунжут, гірчиця', 0, 10);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('chicken-wrap', (SELECT id FROM categories WHERE name = 'Закуски'), 'Твістер з куркою', 189, '280 г', '280', '/images/wrap.webp', '', 'Ніжне соковите куряче філе гриль, свіжий айсберг, стиглий томат, хрусткий огірок і вершково-часниковий соус, загорнуті у хрустку теплу тортилью.', 'Пшенична тортилья, філе курки гриль, салат айсберг, свіжий томат, свіжий огірок, ніжний соус тар-тар', 'Глютен, молоко, яйця', 1, 11);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('fries', (SELECT id FROM categories WHERE name = 'Закуски'), 'Картопля фрі', 89, '150 г', '150', '/images/fries.webp', '', 'Добірна картопля, обсмажена до золотої апетитної скоринки. Хрумка зовні, ніжна всередині, з дрібкою морської солі. Приїжджає гарячою!', 'Картопля сорту Інноватор, олія високоолеїнова, морська сіль', 'Можливий перехресний контакт із глютеном', 0, 12);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('cezar-krevetka', (SELECT id FROM categories WHERE name = 'Салати'), 'Цезар з креветкою', 270, '350 г', '350', '/images/salad.webp', '', 'Обсмажені на грилі тигрові креветки, свіжий хрусткий мікс ромену та айсбергу, перепелині яйця, томати чері, часникові крутони, пармезан і класичний соус цезар.', 'Тигрові креветки, листя ромен та айсберг, перепелині яйця, часникові сухарики, пармезан, томати чері, авторський соус цезар', 'Ракоподібні, яйця, молоко, глютен, риба', 0, 13);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('cezar-chicken', (SELECT id FROM categories WHERE name = 'Салати'), 'Цезар з куркою', 240, '350 г', '350', '/images/chicken-salad.webp', '', 'Ароматне куряче філе гриль, хрустке листя салату ромен, відварені перепелині яйця, солодкі томати чері, золотисті грінки та щедрий пармезан під соусом цезар.', 'Куряче філе sous-vide, листя ромену, перепелині яйця, часникові грінки, витриманий пармезан, чері, фірмовий соус цезар', 'Яйця, молоко, глютен, риба', 1, 14);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('greek', (SELECT id FROM categories WHERE name = 'Салати'), 'Грецький салат', 190, '300 г', '300', '/images/greek.webp', '', 'Справжній середземноморський смак: м’ясисті рожеві томати, польові огірки, солодкий перець, грецькі маслини Каламата, ніжна фета та запашний орегано з олією першого віджиму.', 'Рожеві томати, свіжий огірок, солодкий перець, маслини Каламата, сир фета, червона цибуля, оливкова олія Extra Virgin, орегано', 'Молоко', 0, 15);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('lemonade', (SELECT id FROM categories WHERE name = 'Напої'), 'Лимонад цитрус', 95, '350 мл', '350', '/images/drink.webp', '', 'Освіжаючий авторський лимонад: свіжовичавлений сік лимона й апельсина, гілочки м’яти та бульбашки артезіанської води. Натуральний заряд бадьорості.', 'Свіжовичавлений сік лимона, апельсиновий фреш, свіжа м’ята, газована вода, тростинний сирний сироп', 'Немає основних алергенів', 0, 16);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('cheesecake', (SELECT id FROM categories WHERE name = 'Десерти'), 'Баскський чизкейк', 170, '160 г', '160', '/images/cake.webp', 'СОЛОДКИЙ ХІТ', 'Знаменитий десерт із Сан-Себастьяна: апетитна карамелізована скоринка, тануча кремова серцевина з натурального вершкового сиру та густий соус із лісових ягід.', 'Вершковий сир Філадельфія, вершки 33%, яйця, цукор, ваніль, натуральний соус із лісових ягід', 'Молоко, яйця', 1, 17);
INSERT INTO dishes (slug, category_id, name, price, portion, weight, image_path, tag, description, ingredients, allergens, is_popular, sort_order) VALUES ('company-combo', (SELECT id FROM categories WHERE name = 'Комбо'), 'Комбо для компанії', 699, '2 піци + 2 фрі + 1 л', '2', '/images/combo.webp', 'ВИГІДНО −20%', 'Щедрий сет для друзів або сімейного вечора: піца Пепероні 32 см, піца Маргарита 32 см, дві порції золотистої картоплі фрі та 1 літр крафтового цитрусового лимонаду. Економія понад 180 грн!', 'Піца Пепероні (32 см), піца Маргарита (32 см), 2 порції картоплі фрі, 1 л цитрусового лимонаду', 'Глютен, молоко', 0, 18);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Андрій К.', 'А', 'delivery', 'Доставка', '', 'Замовляли ланч на офіс у районі Політехніки. Кур’єр приїхав рівно через 32 хвилини! Бургери Чіфс у термобоксах були по-справжньому гарячими, м’ясо соковите, а картопля фрі хрумтіла. Дуже крутий рівень доставки для Львова.', '/images/home-combo.png', 'Бургер і картопля фрі з замовлення', 5, 1, 0, 1);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Марія С.', 'М', 'food', 'Їжа', '', 'Пепероні та Чотири сири — абсолютне захоплення! Тісто тонке, повітряне, бортики рум’яні й хрусткі. Моцарели не шкодують, сир тягнеться неймовірно. Окрема подяка за знижку 10% при замовленні онлайн на сайті.', '/images/home-pizza.png', 'Піца пепероні з тягучим сиром', 5, 1, 0, 2);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Іван П.', 'І', 'place', 'Заклад', '', 'Затишний заклад на Київській, 36. Приємне тепле світло, зручні столики, привітна відкрита команда. Часто заходжу пообідати чи забираю замовлення самовивозом дорогою додому. Завжди стабільна висока якість.', '/images/about-interior.png', 'Затишний зал CHECK POINT на вул. Київській', 5, 1, 0, 3);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Оксана Д.', 'О', 'food', 'Їжа', '', 'Цезар із тигровими креветками — один із найкращих у місті: креветки соковиті на грилі, листя свіже та хрумке, пармезан витриманий. А баскський чизкейк із карамельною скоринкою просто тане у роті. Рекомендую всім!', '/images/salad.webp', 'Свіжий салат цезар у закладі', 5, 1, 0, 4);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Тарас В.', 'Т', 'delivery', 'Доставка', '', 'Оформив Комбо тижня на сайті за 1 хвилину, оплатив без комісій через Apple Pay. Жодних зайвих нав’язливих дзвінків оператора — статус відстежується чітко, а кур’єр привіз усе гарячим прямо до квартири.', '/images/combo.webp', 'Комбо сет із бургером та напоєм', 5, 1, 0, 5);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Олена М.', 'О', 'place', 'Заклад', '', 'Чудове місце для сімейного перекусу чи зустрічі з друзями. Діти в захваті від Маргарити та крафтового цитрусового лимонаду, а ми оцінили Подвійний чізбургер. Свіже м’ясо, чистота та швидке приготування.', '/images/contacts-exterior.png', 'Фасад та тераса ресторану CHECK POINT', 5, 1, 0, 6);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Андрій К.', 'А', 'delivery', 'Доставка', 'IT-фахівець, Франківський р-н', 'Бургер Чіфс — просто пушка: котлета з яловичини соковита, булка м’яка, а картопля фрі приїхала гарячою та хрумкою. Кур’єр впорався за 35 хвилин!', '', '', 5, 1, 1, 1);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Марія С.', 'М', 'food', 'Їжа', 'вул. Коновальця', 'Пепероні та Чотири сири — найсмачніші у районі! Тісто тонке, з пухкими бортиками, сиру справді багато. Знижка 10% на сайті робить замовлення ще приємнішим.', '', '', 5, 1, 1, 2);
INSERT INTO reviews (name, initial, category, category_label, role, text, image_path, image_alt, rating, is_published, is_featured, sort_order) VALUES ('Тарас В.', 'Т', 'place', 'Заклад', 'Постійний гість', 'Завжди беру самовивіз на Київській після роботи. Замовлення на сайті займає 1 хвилину, через 15 хвилин забираю без черги зі знижкою. Дуже чисто і привітний сервіс.', '', '', 5, 1, 1, 3);
